// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        address bob = address(0x5678);
        vm.deal(alice, 10 ether);
        vm.prank(alice);
        c.addToBalance{value: 10 ether}();
        vm.prank(bob);
        uint256 result = c.getBalance(alice);
        assertEq(result, 10 ether);
    }
}
